<script setup lang="ts">import{computed}from"vue";import type{LoanHistoryRecord}from"@/domain/library/records";const props=defineProps<{items:LoanHistoryRecord[];loading:boolean}>();const sorted=computed(()=>[...props.items].sort((a,b)=>b.data_emprestimo.localeCompare(a.data_emprestimo)));const label=(s:string)=>({Emprestado:"Emprestado",Atrasado:"Devolução em atraso",Devolvido:"Devolvido",Perdido:"Marcado como perdido",Danificado:"Devolvido com danos",Cancelado:"Empréstimo cancelado"}[s]||s);</script><template><section class="panel loan-history" aria-labelledby="loan-history-title"><h2 id="loan-history-title">Histórico de empréstimos</h2><p v-if="loading" aria-live="polite">A carregar histórico…</p><p v-else-if="!sorted.length">Ainda não existem empréstimos registados.</p><div v-else class="table-wrap"><table><thead><tr><th>Exemplar</th><th>Pessoa</th><th>Estado</th><th>Empréstimo</th><th>Prevista</th><th>Devolução</th><th>Renovações</th></tr></thead><tbody><tr v-for="item in sorted" :key="item.id"><td>{{item.expand?.titulo?.titulo||item.titulo}}</td><td>{{item.expand?.pessoa?.nome||item.pessoa}}</td><td><span class="library-status" :class="`is-${item.estado.toLocaleLowerCase('pt-PT')}`">{{label(item.estado)}}</span></td><td>{{item.data_emprestimo?.slice(0,10)||'—'}}</td><td>{{item.data_prevista?.slice(0,10)||'—'}}</td><td>{{item.data_devolucao?.slice(0,10)||'—'}}</td><td>{{item.renovacoes||0}}</td></tr></tbody></table></div></section></template>
